  ('unit-sappers', 'ruleset-v5-core-curated-1', 'Sappers', 'SUPPORT', 'FORCE_STRENGTH', 2, 0, 0, 4, 0, 6, 'experimental', 'Classes.html row 8 / Sappers; public-v1-companion-classes@1', 'Source values are preserved in definition_json; executable durability, attack and Req values come from the named companion application profile.', '{"sourceRow":8,"description":"Sappers A smaller group of engineers trained move around quietly. Can do everything the Engineers do but quietly. Sappers are an elite group and very few in number.","raw":{"forceStrength":2,"armor":0,"speed":1,"range":1,"cost":null},"specialRules":"Stealth Engineers - Can Build and Repair Structures and Repair Vehicles at 2FS per Repair Action. Can Build Limited Structures. Can Take Limited SF Equipment. Has Stealth Each Build Action makes 3 Building Progress on the project using up 3 Building Supply. Building Supply can be reloaded for 1 General Supply crate. Sappers Have 6/6 Build Supply and come with mines. Mines - Can set mines. Explodes on enemy contact. Structures - Sensor Tower: Build in a hex, reveal area 1 hex out around Sensor Tower. Weapon Emplacement Equipment Upgrades Primary Equipment Slot 1 Secondary Equipment Slot 1","equipmentSlots":{"PRIMARY":1,"SECONDARY":1},"gameplayGaps":["SAPPER_STRUCTURE_LIST","MINES","BUILD_SUPPLY","STEALTH_CONSTRUCTION"],"canonicalActivation":"CATALOGUED","conflictIds":["RC-UNIT-015","RC-V5-014"],"applicationPolicy":{"id":"unit-sappers","name":"Sappers","category":"SUPPORT","healthModel":"FORCE_STRENGTH","maximumHealth":2,"armor":0,"speed":1,"sensorRange":"SCENARIO_DEFINED","requisitionCost":6,"slots":{"PRIMARY":1,"SECONDARY":1},"tags":["GROUND","PERSONNEL","INFANTRY","INFANTRY_STEALTH","ENGINEER","SAPPER"],"allowedOrders":["HOLD","ADVANCE","RUSH","STEALTH"],"allowedActions":["ATTACK","SAPPER_CONSTRUCT","RELOAD_BUILD_SUPPLY"],"weapons":[{"id":"weapon-sapper-carbine-public-v1","name":"Sapper Carbine","damage":{"count":1,"sides":4},"range":1,"armorPiercing":0}],"signatureMechanics":["INFANTRY_STEALTH","BUILD_SUPPLY_6","MINES","SENSOR_TOWER","WEAPON_EMPLACEMENT"],"transportPolicy":["GROUND","PERSONNEL_CARGO"],"decisionReferences":["DEC-006","DEC-021","public-v1-companion-classes@1"]}}'),
  ('unit-mechanized-infantry', 'ruleset-v5-core-curated-1', 'Mechanized Infantry', 'ARMOUR', 'HITS', 3, 2, 0, 12, 0, 10, 'experimental', 'Classes.html row 10 / Mechanized Infantry; public-v1-companion-classes@1', 'Source values are preserved in definition_json; executable durability, attack and Req values come from the named companion application profile.', '{"sourceRow":10,"description":"Mechanized Infantry The only vehicle based unit that can hold a hex like infantry but only from one direction; mechanized infantry can hold 1 forward hex line instead of 3. Mechanized infantry are infantry deployed from armored fighting vehicles","raw":{"forceStrength":3,"armor":2,"speed":3,"range":2,"cost":null},"specialRules":"Can Hold a Center Hex Line Like Infantry. Has the range and speed of a vehicle without the AP of a tank. Can take upgrades from both infantry and vehicle lists. All AP, Armor and Speed upgrades must come from the vehicle list. 1 Primary, 1 Secondary, 1 Internal slot.","equipmentSlots":{"PRIMARY":1,"SECONDARY":1,"INTERNAL":1},"gameplayGaps":["FORWARD_LINE_CONTROL","MIXED_EQUIPMENT_POLICY","FS_VEHICLE_DAMAGE_MODEL"],"canonicalActivation":"CATALOGUED","conflictIds":["RC-UNIT-015","RC-V5-014"],"applicationPolicy":{"id":"unit-mechanized-infantry","name":"Mechanized Infantry","category":"ARMOUR","healthModel":"HITS","maximumHealth":3,"armor":2,"speed":3,"sensorRange":"SCENARIO_DEFINED","requisitionCost":10,"slots":{"PRIMARY":1,"SECONDARY":1,"INTERNAL":1},"tags":["GROUND","VEHICLE","ARMOURED","INFANTRY","MECHANISED"],"allowedOrders":["HOLD","ADVANCE","RUSH"],"allowedActions":["ATTACK","DIG_IN"],"weapons":[{"id":"weapon-mechanized-autocannon-public-v1","name":"Mechanized Autocannon","damage":{"count":1,"sides":4},"range":2,"armorPiercing":0}],"signatureMechanics":["FORWARD_LINE_CONTROL","MIXED_INFANTRY_VEHICLE_EQUIPMENT"],"transportPolicy":["GROUND"],"decisionReferences":["DEC-021","public-v1-companion-classes@1"]}}'),
  ('unit-light-battle-tank', 'ruleset-v5-core-curated-1', 'Light Battle Tank', 'ARMOUR', 'HITS', 3, 2, 0, 12, 0, 10, 'experimental', 'Classes.html row 14 / Light Battle Tank; public-v1-companion-classes@1', 'Source values are preserved in definition_json; executable durability, attack and Req values come from the named companion application profile.', '{"sourceRow":14,"description":"Light Battle Tank Uses for scouting duty, front line combat and capable of being dropped with para-troopers forces out of the back of a Heavy Air Transport. Unlike any other type of tank. These tanks are tipically faster but with less armor then a standard main battle tank.","raw":{"forceStrength":3,"armor":2,"speed":3,"range":2,"cost":null},"specialRules":"AP 2 Fits Inside and be air dropped out of a Heavy Air Transport Armor Weak Spot - Rear Hex Wall Upgrades 1 Secondary 1 Internal","equipmentSlots":{"SECONDARY":1,"INTERNAL":1},"gameplayGaps":["FS_VEHICLE_DAMAGE_MODEL","WEAPON_DAMAGE_PROFILE","HAT_TANK_AIRDROP"],"canonicalActivation":"CATALOGUED","conflictIds":["RC-UNIT-015","RC-V5-014"],"applicationPolicy":{"id":"unit-light-battle-tank","name":"Light Battle Tank","category":"ARMOUR","healthModel":"HITS","maximumHealth":3,"armor":2,"speed":3,"sensorRange":"SCENARIO_DEFINED","requisitionCost":10,"slots":{"SECONDARY":1,"INTERNAL":1},"tags":["GROUND","VEHICLE","ARMOURED","LIGHT","SUBSYSTEMS","REAR_WEAK_SPOT"],"allowedOrders":["HOLD","ADVANCE","RUSH"],"allowedActions":["ATTACK","RELOAD","LOAD","UNLOAD"],"weapons":[{"id":"weapon-light-battle-tank-cannon-public-v1","name":"Light Tank Cannon","damage":{"count":1,"sides":4},"range":2,"armorPiercing":2}],"signatureMechanics":["REAR_WEAK_SPOT","HAT_LIGHT_TANK_AIRDROP"],"transportPolicy":["GROUND","HAT_AIRDROP"],"decisionReferences":["DEC-009","DEC-021","public-v1-companion-classes@1"]}}'),
  ('unit-heavy-battle-tank', 'ruleset-v5-core-curated-1', 'Heavy Battle Tank', 'ARMOUR', 'HITS', 3, 4, 0, 8, 0, 14, 'experimental', 'Classes.html row 16 / Heavy Battle Tank; public-v1-companion-classes@1', 'Source values are preserved in definition_json; executable durability, attack and Req values come from the named companion application profile.', '{"sourceRow":16,"description":"Heavy Battle Tank Heavyer and larger than a standard main battle tank. Up armored with a longer barreled main cannon for increased range. This increase weight limits the transportation options for the Heavy Battle tank. Does not fit inside the Heavy Air Transport.","raw":{"forceStrength":3,"armor":4,"speed":2,"range":3,"cost":null},"specialRules":"AP 2 Armor Weak Spot - Rear Hex Wall Upgrades 1 Secondary 1 Internal","equipmentSlots":{"SECONDARY":1,"INTERNAL":1},"gameplayGaps":["FS_VEHICLE_DAMAGE_MODEL","WEAPON_DAMAGE_PROFILE","HEAVY_TRANSPORT_POLICY"],"canonicalActivation":"CATALOGUED","conflictIds":["RC-UNIT-015","RC-V5-014"],"applicationPolicy":{"id":"unit-heavy-battle-tank","name":"Heavy Battle Tank","category":"ARMOUR","healthModel":"HITS","maximumHealth":3,"armor":4,"speed":2,"sensorRange":"SCENARIO_DEFINED","requisitionCost":14,"slots":{"SECONDARY":1,"INTERNAL":1},"tags":["GROUND","VEHICLE","ARMOURED","HEAVY","SUBSYSTEMS","REAR_WEAK_SPOT"],"allowedOrders":["HOLD","ADVANCE","RUSH"],"allowedActions":["ATTACK"],"weapons":[{"id":"weapon-heavy-battle-tank-cannon-public-v1","name":"Long Heavy Cannon","damage":{"count":1,"sides":8},"range":3,"armorPiercing":2}],"signatureMechanics":["REAR_WEAK_SPOT","HEAVY_CHASSIS"],"transportPolicy":["GROUND","NO_HAT"],"decisionReferences":["DEC-021","public-v1-companion-classes@1"]}}'),
  ('unit-super-heavy-tank', 'ruleset-v5-core-curated-1', 'Super Heavy Tank', 'ARMOUR', 'HITS', 4, 5, 0, 4, 0, 20, 'experimental', 'Classes.html row 17 / Super Heavy Tank; public-v1-companion-classes@1', 'Source values are preserved in definition_json; executable durability, attack and Req values come from the named companion application profile.', '{"sourceRow":17,"description":"Super Heavy Tank \"Single Tank\" This is the king or armored combat. Dual main weapon systems bring more firepower to the field, each cannon larger than even the Heavy Battle Tank. Only specialized transports can move this Behemoth. The biggest issue for a commander of this unit is incredably limited mobility. Unlike every other tank unit this unit is a single tank.","raw":{"forceStrength":4,"armor":5,"speed":1,"range":3,"cost":null},"specialRules":"AP 5 Fires TWICE with each action. Armor Weak Spot - Rear Hex Wall Upgrades 2 Secondary 2 Internal","equipmentSlots":{"SECONDARY":2,"INTERNAL":2},"gameplayGaps":["FS_VEHICLE_DAMAGE_MODEL","DUAL_CANNON_ATTACK","WEAPON_DAMAGE_PROFILE","SPECIAL_TRANSPORT_POLICY"],"canonicalActivation":"CATALOGUED","conflictIds":["RC-UNIT-015","RC-V5-014"],"applicationPolicy":{"id":"unit-super-heavy-tank","name":"Super Heavy Tank","category":"ARMOUR","healthModel":"HITS","maximumHealth":4,"armor":5,"speed":1,"sensorRange":"SCENARIO_DEFINED","requisitionCost":20,"slots":{"SECONDARY":2,"INTERNAL":2},"tags":["GROUND","VEHICLE","ARMOURED","SUPER_HEAVY","SUBSYSTEMS","REAR_WEAK_SPOT"],"allowedOrders":["HOLD","ADVANCE"],"allowedActions":["ATTACK"],"weapons":[{"id":"weapon-super-heavy-dual-cannon-public-v1","name":"Dual Super-heavy Cannons","damage":{"count":1,"sides":8},"range":3,"armorPiercing":5,"attacksPerActivation":2}],"signatureMechanics":["REAR_WEAK_SPOT","TWO_ATTACKS_PER_ACTIVATION"],"transportPolicy":["GROUND","VTOL_HEAVY_LIFT_ONLY"],"decisionReferences":["DEC-021","public-v1-companion-classes@1"]}}'),
  ('unit-light-artillery', 'ruleset-v5-core-curated-1', 'Light Artillery', 'SUPPORT', 'FORCE_STRENGTH', 2, 0, 0, 4, 0, 8, 'experimental', 'Classes.html row 19 / Light Artillery; public-v1-companion-classes@1', 'Source values are preserved in definition_json; executable durability, attack and Req values come from the named companion application profile.', '{"sourceRow":19,"description":"Light Arty A set of light guns able to be deployed and rain fire on distant enemies. While it doesn''t have the damage potential of the heavy artillery these field guns can be moved by the infantry manning them and transported much easier. Light Artillery can be para-dropped from a heavy air transport or brought down in Heavy Drop Pods if an obital has the equipment.","raw":{"forceStrength":2,"armor":0,"speed":1,"range":5,"cost":"0"},"specialRules":"2 Damage, Range 5 Can''t Attack Unless Deployed Action: Deploy - sets up guns to fire. Can''t move while deployed. Action: Abandon Guns - flee from your quipment and turn into a 1FS 1 Speed Infantry Unit. Can retreieve new equipment from a supply depot for 5 supply crates 1 Time for the entire campaign. This unit can dropped from a orbital with the Heavy Drop Pod Upgrade. This unit can para-drop from Heavy Transport Aerospace Craft. 2 Attacks per Action ! Can be all on 1 Hex or split! Indirect Fire - Doesn''t need direct LOS to fire on hostiles and hits all units in HEX targeted. Upgrades 1 Secondary 2 Internal","equipmentSlots":{"SECONDARY":1,"INTERNAL":2},"gameplayGaps":["FIXED_DAMAGE","TWO_ATTACK_SPLIT_FIRE","AREA_HEX_DAMAGE","ABANDON_GUNS","CAMPAIGN_REPLACEMENT"],"canonicalActivation":"CATALOGUED","conflictIds":["RC-UNIT-015","RC-V5-014"],"applicationPolicy":{"id":"unit-light-artillery","name":"Light Artillery","category":"ARTILLERY","healthModel":"FORCE_STRENGTH","maximumHealth":2,"armor":0,"speed":1,"sensorRange":"SCENARIO_DEFINED","requisitionCost":8,"slots":{"SECONDARY":1,"INTERNAL":2},"tags":["GROUND","PERSONNEL","ARTILLERY","INDIRECT","DEPLOYABLE"],"allowedOrders":["HOLD","ADVANCE"],"allowedActions":["ATTACK","DEPLOY","PACK_UP"],"weapons":[{"id":"weapon-light-artillery-public-v1","name":"Light Artillery Battery","damage":{"count":1,"sides":1,"modifier":1},"range":5,"armorPiercing":0,"indirect":true,"attacksPerActivation":2,"areaHex":true}],"signatureMechanics":["DEPLOYED_FIRE","SPLIT_FIRE_TWO","ABANDON_GUNS","ONE_CAMPAIGN_REPLACEMENT"],"transportPolicy":["GROUND","HAT_AIRDROP","HEAVY_DROP_POD"],"decisionReferences":["DEC-021","public-v1-companion-classes@1"]}}'),
  ('unit-heavy-artillery', 'ruleset-v5-core-curated-1', 'Heavy Artillery', 'SUPPORT', 'FORCE_STRENGTH', 3, 0, 0, 0, 0, 12, 'experimental', 'Classes.html row 20 / Heavy Artillery; public-v1-companion-classes@1', 'Source values are preserved in definition_json; executable durability, attack and Req values come from the named companion application profile.', '{"sourceRow":20,"description":"Heavy Arty Called the \"King of the Battlefield\" for a reason. Artillery lobs rounds at the longest ranges. Weakening targets, supporting friendlies and opening holes in the front lines when needed. While having the most out going damage potential Heavy Artillery is the most limited in moblity. Being unable to move without support.","raw":{"forceStrength":3,"armor":0,"speed":0,"range":8,"cost":"0"},"specialRules":"3 Damage, Range 8 Can''t Attack Unless Deployed Action: Deploy - sets up guns to fire. Can''t move while deployed. Action: Abandon Guns - flee from your quipment and tunrin into a 1FS 1 Speed Infantry Unit. Can retreieve new equipment from a supply depot for 5 supply crates. Can be loaded into a Heavy Air Transport. 1 Time for the entire campaign 3 Attacks per Action ! Can be all on 1 Hex or split! Indirect Fire - Doesn''t need direct LOS to fire on hostiles and hits all units in HEX targeted. Upgrades 1 Secondary 2 Internal","equipmentSlots":{"SECONDARY":1,"INTERNAL":2},"gameplayGaps":["FIXED_DAMAGE","THREE_ATTACK_SPLIT_FIRE","AREA_HEX_DAMAGE","ABANDON_GUNS","CAMPAIGN_REPLACEMENT"],"canonicalActivation":"CATALOGUED","conflictIds":["RC-UNIT-015","RC-V5-014"],"applicationPolicy":{"id":"unit-heavy-artillery","name":"Heavy Artillery","category":"ARTILLERY","healthModel":"FORCE_STRENGTH","maximumHealth":3,"armor":0,"speed":0,"sensorRange":"SCENARIO_DEFINED","requisitionCost":12,"slots":{"SECONDARY":1,"INTERNAL":2},"tags":["GROUND","PERSONNEL","ARTILLERY","INDIRECT","DEPLOYABLE","HEAVY"],"allowedOrders":["HOLD"],"allowedActions":["ATTACK","DEPLOY","PACK_UP"],"weapons":[{"id":"weapon-heavy-artillery-public-v1","name":"Heavy Artillery Battery","damage":{"count":1,"sides":1,"modifier":2},"range":8,"armorPiercing":0,"indirect":true,"attacksPerActivation":3,"areaHex":true}],"signatureMechanics":["DEPLOYED_FIRE","SPLIT_FIRE_THREE","ABANDON_GUNS","ONE_CAMPAIGN_REPLACEMENT"],"transportPolicy":["GROUND","HAT_CARGO"],"decisionReferences":["DEC-021","public-v1-companion-classes@1"]}}'),
  ('unit-self-propelled-artillery', 'ruleset-v5-core-curated-1', 'Self-Propelled Artillery', 'SUPPORT', 'HITS', 2, 2, 0, 8, 0, 10, 'experimental', 'Classes.html row 21 / Self-Propelled Artillery; public-v1-companion-classes@1', 'Source values are preserved in definition_json; executable durability, attack and Req values come from the named companion application profile.', '{"sourceRow":21,"description":"Self-Propelled The most mobile of the artillery units. Guns mounted on tracks or wheels.. While they can get up and move and fire without needing to setup and deploy SPG''s do not get multiple shots like other artillery types.","raw":{"forceStrength":2,"armor":2,"speed":2,"range":4,"cost":"0"},"specialRules":"Minimum Range 2, Choose Wheeled or Tracked. (Comes with (5) AP Rounds, Gift from Haven. Once Used they are gone forever) Indirect Fire - Doesn''t need direct LOS to fire on hostiles and hits all units in HEX targeted. Upgrades 1 Secondary 2 Internal","equipmentSlots":{"SECONDARY":1,"INTERNAL":2},"gameplayGaps":["FS_VEHICLE_DAMAGE_MODEL","FIXED_DAMAGE","MINIMUM_RANGE","FINITE_AP_ROUNDS","AREA_HEX_DAMAGE"],"canonicalActivation":"CATALOGUED","conflictIds":["RC-UNIT-015","RC-V5-014"],"applicationPolicy":{"id":"unit-self-propelled-artillery","name":"Self-Propelled Artillery","category":"ARTILLERY","healthModel":"HITS","maximumHealth":2,"armor":2,"speed":2,"sensorRange":"SCENARIO_DEFINED","requisitionCost":10,"slots":{"SECONDARY":1,"INTERNAL":2},"tags":["GROUND","VEHICLE","ARMOURED","ARTILLERY","INDIRECT","SUBSYSTEMS"],"allowedOrders":["HOLD","ADVANCE"],"allowedActions":["ATTACK"],"weapons":[{"id":"weapon-self-propelled-artillery-public-v1","name":"Self-propelled Howitzer","damage":{"count":1,"sides":6},"range":4,"minimumRange":2,"armorPiercing":0,"indirect":true,"areaHex":true,"ammunitionCapacity":5}],"signatureMechanics":["MINIMUM_RANGE_TWO","FIVE_FINITE_AP_ROUNDS"],"transportPolicy":["GROUND"],"decisionReferences":["DEC-021","public-v1-companion-classes@1"]}}'),
  ('unit-vtol-troop-airlift', 'ruleset-v5-core-curated-1', 'VTOL Heavy Troop Airlift', 'AEROSPACE', 'HITS', 3, 1, 0, 20, 0, 12, 'experimental', 'Classes.html row 24 / VTOL Heavy Troop Airlift; public-v1-companion-classes@1', 'Source values are preserved in definition_json; executable durability, attack and Req values come from the named companion application profile.', '{"sourceRow":24,"description":"VTOL Heavy Troop Airlift A infantry focused troop transport that can move multiple platoon of infantry to and from the battlefield as well as some Supply inside its dedicated bay. Forward mounted light weapon offers cover for ground forces.","raw":{"forceStrength":3,"armor":1,"speed":5,"range":1,"cost":"0"},"specialRules":"2 Infantry Unit Capactiy or 1 Supply Cargo Rearm after every FS based Attack Comes with Repelling gear allowing infantry to drop from the VTOL and garrison a building without using an action or requiring the VTOL to land. Upgrades - 1 Light Weapon Mounts 1 Internal Upgrades","equipmentSlots":{"LIGHT":1,"INTERNAL":1},"gameplayGaps":["FS_AEROSPACE_DAMAGE_MODEL","TROOP_OR_SUPPLY_CAPACITY","RAPPELLING_GARRISON","FS_BASED_REARM"],"canonicalActivation":"CATALOGUED","conflictIds":["RC-UNIT-015","RC-V5-014"],"applicationPolicy":{"id":"unit-vtol-troop-airlift","name":"VTOL Heavy Troop Airlift","category":"AEROSPACE","healthModel":"HITS","maximumHealth":3,"armor":1,"speed":5,"sensorRange":"SCENARIO_DEFINED","requisitionCost":12,"slots":{"LIGHT":1,"INTERNAL":1},"tags":["AEROSPACE","VTOL","VEHICLE","ARMOURED","TRANSPORT"],"allowedOrders":["HOLD","ADVANCE"],"allowedActions":["ATTACK","LOAD","UNLOAD","LAND","TAKE_OFF","REARM_AEROSPACE"],"weapons":[{"id":"weapon-vtol-light-gun-public-v1","name":"VTOL Light Gun","damage":{"count":1,"sides":2},"range":1,"armorPiercing":0,"ammunitionCapacity":1}],"signatureMechanics":["TWO_INFANTRY_OR_SUPPLY","RAPPEL_GARRISON","REARM_AFTER_ATTACK"],"transportPolicy":["VTOL","PERSONNEL_OR_SUPPLY"],"decisionReferences":["DEC-021","public-v1-companion-classes@1"]}}'),
  ('unit-vtol-multipurpose-airlift', 'ruleset-v5-core-curated-1', 'VTOL Multi-Purpose Airlift', 'AEROSPACE', 'HITS', 3, 1, 0, 20, 0, 12, 'experimental', 'Classes.html row 25 / VTOL Multi-Purpose Airlift; public-v1-companion-classes@1', 'Source values are preserved in definition_json; executable durability, attack and Req values come from the named companion application profile.', '{"sourceRow":25,"description":"VTOL Multi-Purpose Airlift A smaller VTOL outfitted with enough space for an infantry unit and a single light vehicle unit. Some call it a pelican others with taste a warden.","raw":{"forceStrength":3,"armor":1,"speed":5,"range":1,"cost":"0"},"specialRules":"1 Infantry Unit Capacity or one supply cargo and 1 Light Vehicle Unit Capacity Rearm after every FS based Attack Upgrades - 1 Light Weapon Mounts 1 Internal Upgrades","equipmentSlots":{"LIGHT":1,"INTERNAL":1},"gameplayGaps":["FS_AEROSPACE_DAMAGE_MODEL","SIMULTANEOUS_PERSONNEL_AND_VEHICLE_CARGO","FS_BASED_REARM"],"canonicalActivation":"CATALOGUED","conflictIds":["RC-UNIT-015","RC-V5-014"],"applicationPolicy":{"id":"unit-vtol-multipurpose-airlift","name":"VTOL Multi-Purpose Airlift","category":"AEROSPACE","healthModel":"HITS","maximumHealth":3,"armor":1,"speed":5,"sensorRange":"SCENARIO_DEFINED","requisitionCost":12,"slots":{"LIGHT":1,"INTERNAL":1},"tags":["AEROSPACE","VTOL","VEHICLE","ARMOURED","TRANSPORT"],"allowedOrders":["HOLD","ADVANCE"],"allowedActions":["ATTACK","LOAD","UNLOAD","LAND","TAKE_OFF","REARM_AEROSPACE"],"weapons":[{"id":"weapon-vtol-light-gun-public-v1","name":"VTOL Light Gun","damage":{"count":1,"sides":2},"range":1,"armorPiercing":0,"ammunitionCapacity":1}],"signatureMechanics":["INFANTRY_OR_SUPPLY_PLUS_LIGHT_VEHICLE","REARM_AFTER_ATTACK"],"transportPolicy":["VTOL","MIXED_PERSONNEL_VEHICLE"],"decisionReferences":["DEC-021","public-v1-companion-classes@1"]}}'),
  ('unit-vtol-heavy-lift', 'ruleset-v5-core-curated-1', 'VTOL Heavy Lift', 'AEROSPACE', 'HITS', 3, 3, 0, 20, 0, 14, 'experimental', 'Classes.html row 26 / VTOL Heavy Lift; public-v1-companion-classes@1', 'Source values are preserved in definition_json; executable durability, attack and Req values come from the named companion application profile.', '{"sourceRow":26,"description":"VTOL Heavy Lift Refit for 1 purpose.. To move the heavy equipment. Be they an objective in the field that no one else can move or a friendly Super heavy tank / Mech to bring the pain. Some argue the most powerful team is a VTOL Heavy Lift with a friend.","raw":{"forceStrength":3,"armor":3,"speed":5,"range":0,"cost":"0"},"specialRules":"VTOL Craft No Weapon Can move a single Mech or a Single SHBT, or a Heavy Tank Unit Hollow Mid Section for Lifting Massive Equipment. Can lift 1 Supply Cargo Upgrades - 1 Light Weapon Mounts 1 Internal Upgrades","equipmentSlots":{"LIGHT":1,"INTERNAL":1},"gameplayGaps":["FS_AEROSPACE_DAMAGE_MODEL","EXTERNAL_HEAVY_LIFT","OBJECTIVE_CARGO","HEAVY_TRANSPORT_CAPACITY"],"canonicalActivation":"CATALOGUED","conflictIds":["RC-UNIT-015","RC-V5-014"],"applicationPolicy":{"id":"unit-vtol-heavy-lift","name":"VTOL Heavy Lift","category":"AEROSPACE","healthModel":"HITS","maximumHealth":3,"armor":3,"speed":5,"sensorRange":"SCENARIO_DEFINED","requisitionCost":14,"slots":{"LIGHT":1,"INTERNAL":1},"tags":["AEROSPACE","VTOL","VEHICLE","ARMOURED","TRANSPORT","HEAVY_LIFT"],"allowedOrders":["HOLD","ADVANCE"],"allowedActions":["LOAD","UNLOAD","LAND","TAKE_OFF"],"weapons":[],"signatureMechanics":["EXTERNAL_HEAVY_LIFT","OBJECTIVE_CARGO"],"transportPolicy":["VTOL","ONE_HEAVY_EXTERNAL_LOAD"],"decisionReferences":["DEC-021","public-v1-companion-classes@1"]}}'),
  ('unit-medium-mech', 'ruleset-v5-core-curated-1', 'Medium Mech', 'MECH', 'HITS', 4, 2, 0, 12, 0, 14, 'experimental', 'Classes.html row 31 / Medium Mech; public-v1-companion-classes@1', 'Source values are preserved in definition_json; executable durability, attack and Req values come from the named companion application profile.', '{"sourceRow":31,"description":"Medium Mech Still decently fast for a mech, the medium mech has more space for weapons and equipment.","raw":{"forceStrength":4,"armor":2,"speed":3,"range":0,"cost":"..1"},"specialRules":"2/4 Can''t reload there weapons without being at a supply point due to the scale of the weapon systems. This mech comes with No Weapons. You can transfer your prior Mechs Weapon Mechs can fire all weapons at once or 1 at a time. Legged - Can see over Terrain at lvl 1 higher. Can Crouch to use lvl 1 terrain as cover from direct weapons if blocking LOS.","equipmentSlots":{"EXTERNAL":2,"INTERNAL":4},"gameplayGaps":["FS_MECH_DAMAGE_MODEL","MULTIWEAPON_REFIT","LEG_HEIGHT_LOS","CROUCH_COVER","DOTTED_REQUISITION_COST"],"canonicalActivation":"CATALOGUED","conflictIds":["RC-UNIT-015","RC-V5-014"],"applicationPolicy":{"id":"unit-medium-mech","name":"Medium Mech","category":"MECH","healthModel":"HITS","maximumHealth":4,"armor":2,"speed":3,"sensorRange":"SCENARIO_DEFINED","requisitionCost":14,"slots":{"EXTERNAL":2,"INTERNAL":4},"tags":["GROUND","VEHICLE","ARMOURED","MECH","SUBSYSTEMS","LEGGED"],"allowedOrders":["HOLD","ADVANCE","RUSH"],"allowedActions":["ATTACK","RELOAD","LOAD","UNLOAD","DIG_IN"],"weapons":[{"id":"fitted-mech-weapons","name":"Fitted Mech Weapons","damage":{"count":0,"sides":0},"range":0,"armorPiercing":0,"fittedOnly":true}],"signatureMechanics":["FIRE_ALL_FITTED_WEAPONS","SUPPLY_POINT_RELOAD","LEG_HEIGHT_ONE","CROUCH_COVER"],"transportPolicy":["GROUND","MAGNETIC_CLAMP_CARRIER","VTOL_HEAVY_LIFT"],"decisionReferences":["DEC-021","public-v1-companion-classes@1"]}}'),
  ('unit-heavy-mech', 'ruleset-v5-core-curated-1', 'Heavy Mech', 'MECH', 'HITS', 5, 3, 0, 8, 0, 18, 'experimental', 'Classes.html row 32 / Heavy Mech; public-v1-companion-classes@1', 'Source values are preserved in definition_json; executable durability, attack and Req values come from the named companion application profile.', '{"sourceRow":32,"description":"Heavy Mech Slow but incredably well armored. The heavy mech towers over the battlefield. With its large collections of weapons which can all be fired at once or 1 at a time. If a heavy Mech sees a problem. It probably has a solution.","raw":{"forceStrength":5,"armor":3,"speed":2,"range":0,"cost":"....2"},"specialRules":"3/4 Can''t reload there weapons without being at a supply point due to the scale of the weapon systems. This mech comes with No Weapons. You can transfer your prior Mechs Weapons Mechs can fire all weapons at once or 1 at a time. Legged - Can see over Terrain at lvl 1 higher.","equipmentSlots":{"EXTERNAL":3,"INTERNAL":4},"gameplayGaps":["FS_MECH_DAMAGE_MODEL","MULTIWEAPON_REFIT","LEG_HEIGHT_LOS","DOTTED_REQUISITION_COST"],"canonicalActivation":"CATALOGUED","conflictIds":["RC-UNIT-015","RC-V5-014"],"applicationPolicy":{"id":"unit-heavy-mech","name":"Heavy Mech","category":"MECH","healthModel":"HITS","maximumHealth":5,"armor":3,"speed":2,"sensorRange":"SCENARIO_DEFINED","requisitionCost":18,"slots":{"EXTERNAL":3,"INTERNAL":4},"tags":["GROUND","VEHICLE","ARMOURED","MECH","SUBSYSTEMS","LEGGED","HEAVY"],"allowedOrders":["HOLD","ADVANCE","RUSH"],"allowedActions":["ATTACK","RELOAD","LOAD","UNLOAD"],"weapons":[{"id":"fitted-mech-weapons","name":"Fitted Mech Weapons","damage":{"count":0,"sides":0},"range":0,"armorPiercing":0,"fittedOnly":true}],"signatureMechanics":["FIRE_ALL_FITTED_WEAPONS","SUPPLY_POINT_RELOAD","LEG_HEIGHT_ONE"],"transportPolicy":["GROUND","MAGNETIC_CLAMP_CARRIER","VTOL_HEAVY_LIFT"],"decisionReferences":["DEC-021","public-v1-companion-classes@1"]}}')
