-- Previously catalogued companion infantry use the same named conversion and
-- economy policy while their signature handlers are completed.
UPDATE unit_class_definitions
SET health_model='FORCE_STRENGTH', max_health=3, armor=2,
    speed_quarters=4, requisition_cost=10, definition_status='experimental',
    notes='Executable values are supplied by public-v1-companion-classes@1; source values remain in definition_json.',
    definition_json=json_patch(definition_json, '{"applicationPolicy":{"id":"unit-power-armoured-infantry","name":"Power Armoured Infantry","category":"INFANTRY","healthModel":"FORCE_STRENGTH","maximumHealth":3,"armor":2,"speed":1,"sensorRange":"SCENARIO_DEFINED","requisitionCost":10,"slots":{"PRIMARY":2,"MECH_WEAPON":1},"tags":["GROUND","PERSONNEL","INFANTRY","ARMOURED","POWER_ARMOUR"],"allowedOrders":["HOLD","ADVANCE","RUSH"],"allowedActions":["ATTACK","DIG_IN","SHIELD_WALL","MOUNT_MAGNETIC_CLAMPS","DISMOUNT_MAGNETIC_CLAMPS"],"weapons":[{"id":"weapon-infantry-rifle","name":"Squad Small Arms","damage":{"count":1,"sides":6},"range":1,"armorPiercing":0}],"signatureMechanics":["DIG_IN","SHIELD_WALL","MAGNETIC_CLAMP_RIDER","HEAVY_DROP_POD_INSERTION","UNLOCKABLE_BACK_LIGHT_LASER"],"transportPolicy":["GROUND","HEAVY_DROP_POD"],"decisionReferences":["DEC-021","public-v1-power-armoured-infantry@1"]}}')
WHERE id='unit-power-armoured-infantry' AND ruleset_id='ruleset-v5-core-curated-1';
UPDATE unit_class_definitions
SET health_model='FORCE_STRENGTH', max_health=10, armor=0,
    speed_quarters=4, requisition_cost=4, definition_status='experimental',
    notes='Executable values are supplied by public-v1-companion-classes@1; source values remain in definition_json.',
    definition_json=json_patch(definition_json, '{"applicationPolicy":{"id":"unit-irregular","name":"Irregular Unit","category":"INFANTRY","healthModel":"FORCE_STRENGTH","maximumHealth":10,"armor":0,"speed":1,"sensorRange":"SCENARIO_DEFINED","requisitionCost":4,"slots":{"HIGH_RISK_ARMS":2,"LOW_TECH_MELEE":1},"tags":["GROUND","PERSONNEL","INFANTRY","IRREGULAR"],"allowedOrders":["HOLD","ADVANCE","RUSH"],"allowedActions":["ATTACK","RECRUIT_IRREGULAR"],"weapons":[{"id":"weapon-irregular-small-arms-public-v1","name":"Irregular Small Arms","damage":{"count":1,"sides":6},"range":1,"armorPiercing":0,"outputMultiplier":{"numerator":1,"denominator":4,"rounding":"UP"}}],"signatureMechanics":["QUARTER_DAMAGE_ROUND_UP","POPULATION_RECRUITMENT","CLASS_PROGRESSION"],"transportPolicy":["GROUND","PERSONNEL_CARGO"],"decisionReferences":["DEC-021","public-v1-companion-classes@1"]}}')
WHERE id='unit-irregular' AND ruleset_id='ruleset-v5-core-curated-1';
UPDATE unit_class_definitions
SET health_model='FORCE_STRENGTH', max_health=3, armor=0,
    speed_quarters=8, requisition_cost=8, definition_status='experimental',
    notes='Executable values are supplied by public-v1-companion-classes@1; source values remain in definition_json.',
    definition_json=json_patch(definition_json, '{"applicationPolicy":{"id":"unit-special-forces","name":"Special Forces","category":"INFANTRY","healthModel":"FORCE_STRENGTH","maximumHealth":3,"armor":0,"speed":2,"sensorRange":"SCENARIO_DEFINED","requisitionCost":8,"slots":{"PRIMARY":2,"SECONDARY":2},"tags":["GROUND","PERSONNEL","INFANTRY","INFANTRY_STEALTH","SPECIAL_FORCES"],"allowedOrders":["HOLD","ADVANCE","RUSH","STEALTH"],"allowedActions":["ATTACK","PLACE_DELAYED_CHARGE","DETONATE_DELAYED_CHARGE"],"weapons":[{"id":"weapon-special-forces-quiet-rifle-public-v1","name":"Quiet Rifle","damage":{"count":1,"sides":4},"range":1,"armorPiercing":0}],"signatureMechanics":["INFANTRY_STEALTH","DELAYED_CHARGE"],"transportPolicy":["GROUND","PERSONNEL_CARGO"],"decisionReferences":["DEC-021","public-v1-companion-classes@1"]}}')
WHERE id='unit-special-forces' AND ruleset_id='ruleset-v5-core-curated-1';

UPDATE ruleset_implementation_overlays
SET requisition_status='PUBLISHED', availability_status='BLOCKED',
    reason_code='COMPANION_HANDLER_PENDING',
    overlay_json=json_patch(overlay_json, '{"economyPolicyId":"public-v1-companion-classes@1"}')
WHERE ruleset_id='ruleset-v5-core-curated-1' AND definition_kind='UNIT'
  AND definition_id IN ('unit-irregular','unit-special-forces');

UPDATE ruleset_implementation_overlays
SET implementation_status='IMPLEMENTED', requisition_status='PUBLISHED', availability_status='AVAILABLE',
    executable=1, purchasable=1, reason_code=NULL,
    overlay_json=json_patch(overlay_json, '{"gameplayGaps":[],"applicationProfileId":"public-v1-power-armoured-infantry@1"}')
WHERE ruleset_id='ruleset-v5-core-curated-1' AND definition_kind='UNIT'
  AND definition_id='unit-power-armoured-infantry';

