UPDATE unit_class_definitions
SET definition_status='active'
WHERE id IN ('unit-power-armoured-infantry','unit-irregular','unit-special-forces','unit-sappers','unit-light-artillery','unit-heavy-artillery','unit-self-propelled-artillery','unit-vtol-troop-airlift','unit-vtol-multipurpose-airlift','unit-vtol-heavy-lift','unit-mechanized-infantry','unit-light-battle-tank','unit-heavy-battle-tank','unit-super-heavy-tank','unit-medium-mech','unit-heavy-mech') AND ruleset_id='ruleset-v5-core-curated-1';

UPDATE ruleset_implementation_overlays
SET implementation_status='IMPLEMENTED', requisition_status='PUBLISHED', availability_status='AVAILABLE',
    executable=1, purchasable=1, reason_code=NULL,
    overlay_json=json_patch(overlay_json, '{"gameplayGaps":[],"applicationProfileId":"public-v1-irregular@1"}')
WHERE definition_kind='UNIT' AND definition_id='unit-irregular' AND ruleset_id='ruleset-v5-core-curated-1';

